Lemma fields_L : forall (d : pst) (c' : pcore) (SP : Z) (mh m' : mem) (s s' : as_St H) LBn' S' L' ns' ls' em' (g' : bool) (A' : Z),
  let LB := ps_LBn d ++ LB0 in
  PutL H sp P E p0 bs LB0 (ps_L d0) (ps_es d0) (ps_h d0) d ->
  aceil <= SP -> SP <= bv_unsigned sp ->
  as_RHEAP H s LB mh -> HdrOwnA LB mh (ps_h d) -> AMBuf mh (P + 168) (ps_es d) (ps_insz d) ->
  AFieldsC mh (P + 80) (ps_S d) (ps_L d) (ps_ns d) (ps_ls d) (ps_em d) ->
  as_RHEAP H s' (LBn' ++ LB) m' ->
  AFieldsC m' (P + 80) S' L' ns' ls' em' -> AFieldsOwn (LBn' ++ LB) em' ->
  new_elems_off H LB SP (ps_L d) L' -> lsub (ps_L d) L' -> lbn_own L' LBn' ->
  pcore_ok c' -> pc_state c' = pc_state (ps_c d) -> pc_skip c' = pc_skip (ps_c d) -> pc_hlim c' <= pc_hlim (ps_c d) -> 2 <= pc_state c' ->
  (pc_state c' = 3 \/ pc_state c' = 4 \/ pc_state c' = 9 -> 1 <= pc_len c') ->
  ps_A d <= A' ->
  PutL H sp P E p0 bs LB0 (ps_L d0) (ps_es d0) (ps_h d0)
